/* Published-rule arithmetic; no probabilistic admissions model or synthetic outcomes. */
var AdmissionReadiness=(()=>{
 function frontier(grades,minimum=2.3,average=2.6){const fixed=grades.filter(g=>g!==null),missing=grades.length-fixed.length,knownSum=fixed.reduce((n,g)=>n+g,0),needed=missing?(average*grades.length-knownSum)/missing:null;let considered=0,feasible=0;const examples=[];function visit(i,row){if(i===grades.length){considered++;if(row.every(g=>g>=minimum)&&row.reduce((n,g)=>n+g,0)/row.length>=average-1e-9){feasible++;if(examples.length<5)examples.push([...row])}return}if(grades[i]!==null)return visit(i+1,[...row,grades[i]]);for(let value=23;value<=40;value++)visit(i+1,[...row,value/10])}visit(0,[]);return{missing,neededAverage:needed===null?null:Math.max(minimum,needed),possible:feasible>0,considered,feasible,examples}}
 return{frontier};
})();if(typeof module!=='undefined')module.exports=AdmissionReadiness;
function eeAdmissionReadiness(){const records=AcademicPathway.records(state),codes=['STMATH 124','STMATH 125','B PHYS 121'],rows=codes.map(code=>{const req=AcademicPathway.requirements.find(c=>c.code===code),record=AcademicPathway.completion(req,records),grade=record?AcademicPathway.gradeValue(record):null;return{code,record,grade}}),frontier=AdmissionReadiness.frontier(rows.map(r=>r.grade)),comp=AcademicPathway.completion(AcademicPathway.requirements.find(c=>c.code==='B WRIT 134'),records),official=typeof state.profile?.reportedEEGpa==='number'&&Number.isFinite(state.profile.reportedEEGpa)&&state.profile.reportedEEGpa>=0&&state.profile.reportedEEGpa<=4?state.profile.reportedEEGpa:undefined;return `<details class="journey-advanced"><summary>Check my UWB EE minimum preparation</summary><p>Uses the published UWB EE minimums and the source-verified mappings in Camino. Missing classes or unrecognized equivalents remain unknown. These checks are unofficial; source policies and all application requirements still apply.</p><div class="table-wrap"><table><thead><tr><th>Prerequisite</th><th>Observed grade</th><th>Published minimum</th><th>Check</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.code)}</td><td>${r.grade===null?'Not matched':r.grade.toFixed(2)}</td><td>2.30</td><td>${r.grade===null?'Needs coursework / equivalency review':r.grade>=2.3?'Meets this numeric minimum':'Below this minimum — review a retake or advising options'}</td></tr>`).join('')}<tr><td>College English composition</td><td>${comp?esc(comp.grade):'Not matched'}</td><td>2.00</td><td>${comp?'Matched course meets entered numeric minimum':'Confirm a qualifying course and grade'}</td></tr></tbody></table></div><p>The published average across Calculus I, Calculus II and Mechanics must be at least 2.6. ${rows.every(r=>r.grade!==null)?'Simple mean of matched grades: '+(rows.reduce((n,r)=>n+r.grade,0)/3).toFixed(3)+'.':'Some prerequisite grades are not yet matched.'} Confirm the institution’s calculation and repeat policy, especially across colleges with different credit values.</p><h3>Grade scenarios, not odds</h3><p>${frontier.missing?`For the ${frontier.missing} unmatched prerequisite(s), a simple-average scenario needs at least ${frontier.neededAverage.toFixed(2)} on average, with each class at least 2.3.`:'No future-grade placeholders remain in this arithmetic check.'} ${frontier.possible?'':'The fixed observed grades do not meet the minimums in these scenarios; a retake or advising review may be needed.'}</p><p>Checked ${frontier.considered.toLocaleString()} combinations on a 0.1 grade grid from 2.3 to 4.0 for unmatched courses; ${frontier.feasible.toLocaleString()} satisfy the entered numeric constraints under equal weighting. These combinations are not sampled applicant outcomes, probabilities or forecasts of your grades.</p><h3>Cumulative admission GPA</h3><p>Published minimum: 2.70. A record estimate by institution is not automatically the admission GPA across transferable coursework.</p><form id="reported-ee-gpa"><label>Your reported cumulative GPA under the college's policy<input name="gpa" type="number" min="0" max="4" step="0.01" required value="${esc(official??'')}"></label><button class="btn">Compare reported GPA</button></form>${official!==undefined?`<p>Your reported ${Number(official).toFixed(2)} ${Number(official)>=2.7?'meets':'is below'} the published numeric minimum. This value and its policy basis have not been independently verified.</p>`:''}<a class="journey-secondary" href="${AcademicEvidence.uwbEE.source}" target="_blank" rel="noopener">Official EE admission criteria ↗</a></details>`}
AdmissionReadiness.calendar=(()=>{
 const escape=s=>String(s??'').replace(/\\/g,'\\\\').replace(/\r\n|\r|\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
 function uid(row){const identity=JSON.stringify([row.date,row.label||row.title||'',row.institution||'',row.cycle||'',row.track||'']);let a=2166136261,b=2246822519;for(const ch of identity){const n=ch.codePointAt(0);a=Math.imul(a^n,16777619)>>>0;b=Math.imul(b^n,3266489917)>>>0}return 'camino-'+a.toString(16).padStart(8,'0')+b.toString(16).padStart(8,'0')+'@camino.local'}
 function fold(line){let text='',bytes=0;for(const ch of line){const n=ch.codePointAt(0),size=n<=127?1:n<=2047?2:n<=65535?3:4;if(bytes+size>75){text+='\r\n ';bytes=1}text+=ch;bytes+=size}return text}
 function validDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const d=new Date(value+'T00:00:00Z');return Number.isFinite(+d)&&d.toISOString().slice(0,10)===value}
 function generate(rows,{now=new Date(),personal=false}={}){if(rows.some(r=>!validDate(r.date)))throw Error('Correct the checkpoint dates before exporting the calendar.');const stamp=now.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Camino//Planning Checkpoints//EN'];for(const row of rows){const basis=typeof DeadlineCore!=='undefined'?DeadlineCore.basisLabel(row):row.dateBasis?'Source-backed reminder; verify basis':'Entered reminder',description=personal?'Personal planning date. Not an institution-verified deadline.':[row.cycle,row.track,basis,'Planning reminder; verify closing time and current-cycle applicability.',row.source].filter(Boolean).join(' · ');lines.push('BEGIN:VEVENT','UID:'+uid(row),'DTSTAMP:'+stamp,'DTSTART;VALUE=DATE:'+row.date.replaceAll('-',''),'SUMMARY:'+escape([row.label||row.title,row.institution].filter(Boolean).join(' · ')),'DESCRIPTION:'+escape(description),'END:VEVENT')}lines.push('END:VCALENDAR');return lines.map(fold).join('\r\n')+'\r\n'}
 return{escape,uid,fold,validDate,generate};
})();
function checkpointCalendar(){try{download('camino-application-checkpoints.ics',AdmissionReadiness.calendar.generate(state.advisingDates||[]),'text/calendar');toast('Calendar downloaded. Import it into your calendar app and set reminders.')}catch(error){toast(error.message)}}
function installAdmissionReadiness(){const prior=advisingPage;advisingPage=()=>prior()+eeAdmissionReadiness();const priorCheckpoints=advisingCheckpoints;advisingCheckpoints=()=>priorCheckpoints()+((state.advisingDates||[]).length?'<button class="btn" data-checkpoint-calendar>Download checkpoints calendar ↓</button>':'');const beforeBind=bind;bind=()=>{beforeBind();document.querySelector('#reported-ee-gpa')?.addEventListener('submit',e=>{e.preventDefault();const n=+new FormData(e.target).get('gpa');if(!Number.isFinite(n)||n<0||n>4)return toast('Enter a GPA between 0 and 4.');state.profile={...state.profile,reportedEEGpa:n};save();render()});document.querySelectorAll('[data-checkpoint-calendar]').forEach(b=>b.onclick=checkpointCalendar)}}
